import React, { useEffect, useState } from 'react';
import { Box, Typography, Card, CardContent, Button, Stack, useTheme } from '@mui/material';
import MinimalAppBar from '../../Component/MinimalAppBar';
import callApi from '../../Services/callApi';
import { AnimatePresence, motion } from 'framer-motion';
import { Outlet, useNavigate } from 'react-router-dom';
import InstallmentProgress from '../../Component/InstallmentProgress';
import UploadSlipModal from '../../Component/UploadSlipModal';
import Swal from 'sweetalert2';
import { uploadImageService } from '../../Services/uploadImageService';
import Loader from '../../Component/Loader';
import { CloudUpload } from '@mui/icons-material';

const DownPayment = () => {
  const [isLoader, setIsLoader] = useState<boolean>(false);
  const navigate = useNavigate();
  const [data, setData] = useState<any[]>([]);
  const [item, setItem] = useState<any>();
  const theme = useTheme();
  const [currentIndex, setCurrentIndex] = useState(0);

  const [showUploadModal, setShowUploadModal] = useState(false);

  useEffect(() => {
    onLoad();
  }, [])

  useEffect(() => {
    setItem(data[currentIndex]);
  }, [currentIndex])

  const onLoad = async () => {
    setIsLoader(true)
    var res = await callApi.get('/Preorders/myOrder');
    setIsLoader(false)
    if (res.data?.success) {
      setItem(res.data?.data[currentIndex]);
      setData(res.data?.data);
    }
  }

  const handleNext = () => {
    setCurrentIndex((prev) => (prev < data.length - 1 ? prev + 1 : prev));
  };

  const handlePrev = () => {
    setCurrentIndex((prev) => (prev > 0 ? prev - 1 : prev));
  };

  async function handleSlipUpload(file: File) {
    try {
      setIsLoader(true)
      var result = await uploadImageService(`Slip/DOWN/${item.id}/upload`, file);
      setIsLoader(false)
      if (result?.success === true) {
        Swal.fire('แจ้งเตือน', result?.message, 'info')
        onLoad();
        // Close modal logic is handled by the Modal's onSubmit wrapper if needed, 
        // but here we just wait for it to finish.
      } else {
        Swal.fire('เกิดข้อผิดพลาดในการอัปโหลด', result?.message)
        throw new Error(result?.message); // Throw to stop modal from closing/clearing if we wanted, but Modal closes on success usually 
      }
    } catch (error) {
      console.error("Error uploading slip:", error);
      setIsLoader(false);
      throw error;
    }
  }

  return (
    <>
      <Loader isLoader={isLoader} />
      {item && (
        <UploadSlipModal
          open={showUploadModal}
          onClose={() => setShowUploadModal(false)}
          onUpload={handleSlipUpload}
          title={`อัปโหลดสลิปใบจอง #${item.id}`}
        />
      )}

      <MinimalAppBar onBack={() => window.history.back()} title={`ใบจองของฉัน`}></MinimalAppBar>
      <AnimatePresence mode="wait">
        {item && <motion.div
          key={item.id}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          exit={{ opacity: 0, y: -20 }}
          transition={{
            duration: 0.6,
            ease: [0.25, 0.8, 0.25, 1],
          }}
        >
          <Box p={2} pb={10}>
            {/* Card wrapper */}
            <Card
              elevation={3}
              sx={{
                borderRadius: 4,
                overflow: 'visible',
                mb: 3,
                background: theme.palette.background.paper
              }}
            >
              <CardContent sx={{ p: 3 }}>
                <Stack spacing={2} alignItems="center" mb={2}>
                  <Typography variant="h6" color="primary" fontWeight="bold">
                    #{item.id} - {item.orderType}
                  </Typography>

                  {/* Progress Component */}
                  <InstallmentProgress totalAmount={item?.amount} paidAmount={item?.paid} />

                  {/* Details Summary */}
                  <Box
                    sx={{
                      width: '100%',
                      bgcolor: theme.palette.grey[50],
                      p: 2,
                      borderRadius: 2
                    }}
                  >
                    <Stack spacing={1}>
                      <Box display="flex" justifyContent="space-between">
                        <Typography variant="body2" color="text.secondary">ราคาสินค้า</Typography>
                        <Typography variant="body2">฿{item.amount.toLocaleString()}</Typography>
                      </Box>
                      {item.disCount > 0 && (
                        <Box display="flex" justifyContent="space-between">
                          <Typography variant="body2" color="text.secondary">ส่วนลด</Typography>
                          <Typography variant="body2" color="error">
                            -฿{item.disCount.toLocaleString()}
                          </Typography>
                        </Box>
                      )}
                      {item.promotion && (
                        <Box display="flex" justifyContent="space-between">
                          <Typography variant="body2" color="text.secondary">โปรโมชั่น</Typography>
                          <Typography variant="body2" color="primary">
                            {item.promotion}
                          </Typography>
                        </Box>
                      )}
                    </Stack>
                  </Box>
                </Stack>

                <Stack spacing={2} mt={3}>
                  <Button
                    fullWidth
                    variant="outlined"
                    size="large"
                    onClick={() => navigate('detail', { state: item })}
                    sx={{ borderRadius: 3 }}
                  >
                    ดูรายละเอียดสัญญา
                  </Button>
                  <Button
                    fullWidth
                    variant="contained"
                    size="large"
                    startIcon={<CloudUpload />}
                    onClick={() => setShowUploadModal(true)}
                    sx={{
                      borderRadius: 3,
                      bgcolor: theme.palette.primary.main,
                      color: '#fff'
                    }}
                  >
                    อัปโหลดสลิป
                  </Button>
                </Stack>
              </CardContent>
            </Card>

            {/* Navigation Controls */}
            <Stack direction="row" spacing={2} alignItems="center" justifyContent="center">
              <Button
                variant="contained"
                onClick={handlePrev}
                disabled={currentIndex === 0}
                sx={{ borderRadius: 8, minWidth: 40 }}
              >
                &lt;
              </Button>
              <Typography variant="body2" color="text.secondary">
                รายการที่ {currentIndex + 1} จาก {data.length}
              </Typography>
              <Button
                variant="contained"
                onClick={handleNext}
                disabled={currentIndex === data.length - 1}
                sx={{ borderRadius: 8, minWidth: 40 }}
              >
                &gt;
              </Button>
            </Stack>
          </Box>
        </motion.div>}
      </AnimatePresence>
    </>
  );
};

export default DownPayment;
